import { CommonModule } from '@angular/common';
import { Component, HostListener, OnInit } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { environment } from '../../../../../environments/environment';

@Component({
  selector: 'app-all-members',
  standalone: true,
  imports: [CommonModule],
  templateUrl: './all-members.component.html',
  styleUrls: ['./all-members.component.scss']
})
export class AllMembersComponent implements OnInit {
  cadres: any[] = [];
  page = 1;             // start at page 1
  limit = 10;           // API page size
  total = 0;            // total records from API
  loading = false;
  allLoaded = false;    // set on the last or an empty page so we never keep calling the API

  constructor(private http: HttpClient) {}

  ngOnInit(): void {
    this.loadCadres();
  }

  loadCadres(): void {
    if (this.loading || this.allLoaded) return;

    this.loading = true;
    this.http.get<any>(
      `${environment.apiUrl}/admin/users?page=${this.page}&limit=${this.limit}&role=user&sortby=designation&hasProfilePic=true`
    ).subscribe({
      next: (res) => {
        const newData = res.data?.data || [];

        // ✅ Simply merge new data as received
        this.cadres = [...this.cadres, ...newData];

        // Update total and page for next request
        this.total = +res.data?.pagination?.total || 0;
        this.page++;
        this.allLoaded = newData.length === 0 || this.cadres.length >= this.total;

        this.loading = false;

        // Members without a profile pic are hidden, so a page can add little or no height.
        // If the page still can't be scrolled, onScroll never fires: fetch the next page ourselves
        // once the new cards are rendered.
        setTimeout(() => {
          if (this.isNearBottom()) this.loadCadres();
        });
      },
      error: (err) => {
        console.error('Error fetching cadres:', err);
        this.loading = false;
      }
    });
  }

  private isNearBottom(): boolean {
    const scrollPosition = window.innerHeight + window.scrollY;
    const threshold = document.body.offsetHeight - 100; // 100px before bottom
    return scrollPosition >= threshold;
  }

  // Trigger loading when near bottom
  @HostListener('window:scroll', [])
  onScroll(): void {
    if (this.isNearBottom()) {
      this.loadCadres();
    }
  }
}
